    Write-Host "  ⚠️ Proxy network failed, trying direct..." -ForegroundColor Yellow
    try {
        $testRes = Invoke-RestMethod -Uri "https://api.vercel.com/v2/projects?teamId=team_NGXWfFxSgU04Qc4U9AlWlHGT" `
