const fs = require('fs');
const path = require('path');

async function uploadFile(filePath) {
  const content = Buffer.from(fs.readFileSync(path.join('public/images', filePath))).toString('base64');

  // Check if file already exists on GitHub to get its sha
  let sha = null;
  try {
    const checkRes = await fetch(`https://api.github.com/repos/mouxia1980/personal-website/contents/public/images/${filePath}`, {
      headers: { 'Authorization': `token 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`, 'User-Agent': 'codex' }
    });
    if (checkRes.ok) sha = (await checkRes.json()).sha;
  } catch(e) {}

  // PUT to create or update the file
  const res = await fetch(`https://api.github.com/repos/mouxia1980/personal-website/contents/public/images/${filePath}`, {
    method: 'PUT',
    headers: { 
      'Authorization': `token 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`,
      'Content-Type': 'application/json',
      'User-Agent': 'codex'
    },
    body: JSON.stringify({ message: `Add ${filePath}`, content, ...(sha && { sha }) }),
    signal: AbortSignal.timeout(5000)
  });

  const data = await res.json();
  return res.ok;
}

async function main() {
  console.log('Uploading all images to GitHub master branch...');

  const images = fs.readdirSync('public/images');
  let okCount = 0;

  for (const img of images) {
    try {
      const ok = await uploadFile(img);
