# Access the latest Vercel deployment preview URL to see what it shows
$script = @'
const https = require('https');
const http = require('http');

// Check the preview URL content
async function checkUrl(url) {
  return new Promise((resolve, reject) => {
    const parsed = new URL(url);

    const req = (parsed.protocol === 'https:' ? https : http).request({
      hostname: parsed.hostname,
      path: parsed.pathname || '/',
      method: 'GET',
      timeout: 10000
    }, res => {
      let data = '';
      res.on('data', d => data += d);
      res.on('end', () => resolve({ 
        status: res.statusCode,
        headers: res.headers,
        body: data.substring(0,500)
      }));
    });

    req.on('error', e => resolve({ error: e.message }));
    req.on('timeout', () => { req.destroy(); resolve({ error: 'timeout' }); });
    req.end();
  });
}

async function main() {
  const urls = [
    'https://print-html-v3-5phomqvlv-mouxia.vercel.app',
    'https://print-html-v3-7dlo1hc0y-mouxia.vercel.app'
  ];

  for (const url of urls) {
    console.log(`\n=== ${url} ===`);
    const result = await checkUrl(url);

    if (result.error) {
      console.log(`Error: ${result.error}`);
    } else {
      console.log(`Status: ${result.status}`);

      // Check for SEO-related headers
      const seoHeaders = ['x-frame-options', 'content-type', 'strict-transport-security'];
      seoHeaders.forEach(h => {
        if (result.headers[h]) console.log(`${h}: ${result.headers[h]}`);
      });

      // Check body for relevant content
      if (result.body) {
        const hasImg = result.body.includes('<img') || result.body.includes('alt=');
        const hasPackaging = result.body.toLowerCase().includes('packaging') || result.body.toLowerCase().includes('印刷');

        console.log(`Contains <img tags: ${hasImg}`);
        console.log(`Contains packaging keywords: ${hasPackaging}`);

        // Show relevant parts of body
        const metaMatch = result.body.match(/<meta[^>]*>/g);
        if (metaMatch && metaMatch.length > 0) {
          console.log('\nMeta tags found:');
          metaMatch.slice(0,5).forEach(m => console.log(m));
        }
      }
    }
  }
}

main();
