    const req = https.request(options, res => {
      let data = '';
      res.on('data', d => data += d);
      res.on('end', () => resolve({ ok: res.statusCode < 400, name: img }));
    });

    req.setTimeout(6000, () => {
      req.destroy();
      uploadImage(img, attempt + 1).then(r => resolve(r));
